// Recorremos los datos
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  // Vamos a buscar el archivo binario al disco duro de n8n
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');

  // Lo transformamos a texto Base64
  items[i].json.fotoBase64 = buffer.toString('base64');
}

return items;

const items = $input.all();
const result = [];

// Detecta qué botón tocó el usuario
const callbackData = $('Telegram Trigger').first().json.callback_query?.data || 'pub_1';

for (const item of items) {
  const originalUrl = item.json.ImageURL;
  const transformedUrl = originalUrl.replace('/upload/', '/upload/c_pad,ar_1:1,w_1080,b_white/');

  // Elige el caption correcto según el botón
  let captionIG;
  if (callbackData === 'pub_final' && item.json.Copy_Final) {
    captionIG = item.json.Copy_Final;      // texto editado por el usuario
  } else if (callbackData === 'pub_2') {
    captionIG = item.json.Copy_Op2;        // opción 2
  } else if (callbackData === 'pub_3') {
    captionIG = item.json.Copy_Op3;        // opción 3
  } else {
    captionIG = item.json.Copy_Op1;        // opción 1 (default)
  }

  result.push({
    json: {
      ...item.json,
      ImageURL_IG: transformedUrl,
      Caption_IG: captionIG
    }
  });
}

return result;

const items = $input.all();
const result = [];

// Patrones prohibidos por Mary Kay
const patronesPrecios = [
  /\$\s?\d+/g,                    // $1500, $ 1500
  /\d+[\.,]\d{3}/g,               // 1.500, 1,500
  /\d+%\s?(off|desc)/gi,          // 50% off, 50% desc
  /\b(oferta|promocion|promo|descuento|rebaja|barato|economico|gratis)\b/gi
];

const FIRMA_OBLIGATORIA = "-- Consultora de Belleza Independiente Mary Kay --";

for (const item of items) {
  let caption = item.json.Caption_IG || '';
  let precioDetectado = false;
  let patronEncontrado = '';

  // 1. DETECCIÓN DE PRECIOS
  for (const patron of patronesPrecios) {
    const match = caption.match(patron);
    if (match) {
      precioDetectado = true;
      patronEncontrado = match[0];
      break;
    }
  }

  // 2. Si hay precio, bloquea y avisa
  if (precioDetectado) {
    result.push({
      json: {
        ...item.json,
        compliance_ok: false,
        compliance_error: `⚠️ Postly detectó contenido prohibido: "${patronEncontrado}". Por las normas de Mary Kay no podés publicar precios ni promociones en el feed. Editá el texto e intentá de nuevo.`
      }
    });
    continue;
  }

  // 3. VERIFICAR Y AGREGAR FIRMA
  if (!caption.includes(FIRMA_OBLIGATORIA)) {
    caption = caption + '\n' + FIRMA_OBLIGATORIA;
  }

  result.push({
    json: {
      ...item.json,
      Caption_IG: caption,
      compliance_ok: true,
      compliance_error: null
    }
  });
}

return result;

const items = $input.all();
const chatId = $('Telegram Trigger').first().json.message.chat.id;

if (items.length === 0) {
  return [{
    json: {
      chatId: chatId,
      texto: '📭 Todavía no tenés publicaciones en tu agenda.\n\nTocá 🚀 Nueva Publicación para crear tu primer post.',
      sinDatos: true
    }
  }];
}

const result = [];

for (const item of items) {
  const status = item.json.Status === 'Publicado' ? '🟢 Publicado' : '🔴 Pendiente';
  const fecha = item.json.Timestamp 
    ? new Date(item.json.Timestamp).toLocaleDateString('es-AR', { day: '2-digit', month: '2-digit', year: 'numeric' })
    : 'Sin fecha';

  const copyResumen = (item.json.Copy_Final || item.json.Copy_Op1 || '').substring(0, 100) + '...';

  const texto = `${status} — ${fecha}\n\n📝 ${copyResumen}`;

  result.push({
    json: {
      chatId: chatId,
      texto: texto,
      imageURL: item.json.ImageURL || null,
      sinDatos: false
    }
  });
}

return result;
